ok = bad = 0
out = open(OUT, 'w')
for pid, path in PAIRS:
    try:
        try:
            data = cf.get_res_file(path, '')
        except Exception:
            data = None
        if data and (data[:4] == SIGS[0] or data[:3] == SIGS[1]):
            open(os.path.join(d, '%d.png' % pid), 'wb').write(data)
            ok += 1
            continue
        data = cf.get_res_file(path.rsplit('.', 1)[0] + '.pkm', '')
        if data and data[:4] == 'PKM ':
            open(os.path.join(d, '%d.pkm' % pid), 'wb').write(data)
            ok += 1
        else:
            out.write('nopng %d %s %r\n' % (pid, path, (data or '')[:8]))
            bad += 1
    except Exception as e:
        out.write('fail %d %s %r\n' % (pid, path, e))
        bad += 1
out.write('ok=%d bad=%d\n' % (ok, bad))
out.close()
